,"postgres","service_role","MAINTAIN",false],["recipes","postgres","service_role","REFERENCES",false],["recipes","postgres","service_role","SELECT",false],["recipes","postgres","service_role","TRIGGER",false],["recipes","postgres","service_role","TRUNCATE",false],["recipes","postgres","service_role","UPDATE",false]]}$captured$::jsonb;
  new_qual text := $newqual$(EXISTS ( SELECT 1
   FROM recipes r
  WHERE ((r.id = recipe_reviews.recipe_id) AND (r.is_published IS TRUE) AND (r.is_verified IS TRUE))))$newqual$;
  current_state jsonb;
  expected_after jsonb;
  full_columns_before jsonb;
  full_constraints_before jsonb;
  full_columns_now jsonb;
  full_constraints_now jsonb;
  pass integer;
BEGIN
  IF current_user <> 'postgres' THEN
    RAISE EXCEPTION 'Review boundary requires the reviewed postgres execution role';
  END IF;
  SELECT jsonb_set(expected, '{policies}', jsonb_agg(
    CASE WHEN value->>'tablename' = 'recipe_reviews' AND value->>'policyname' = 'Public read reviews'
      THEN value || jsonb_build_object('qual', new_qual) ELSE value END
    ORDER BY (value->>'tablename') COLLATE "C", (value->>'policyname') COLLATE "C"))
  INTO expected_after FROM jsonb_array_elements(expected->'policies');
  FOR pass IN 0..1 LOOP
    SELECT jsonb_build_object(
      'policies', (SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY tablename COLLATE "C", policyname COLLATE "C"), '[]'::jsonb)
        FROM pg_policies p WHERE schemaname = 'public' AND tablename IN
        ('recipes','recipe_ingredients','recipe_steps','recipe_media','recipe_reviews','recipe_submissions')),
      'relations', (SELECT jsonb_agg(jsonb_build_object('table',c.relname,'owner',pg_get_userbyid(c.relowner),
        'enabled',c.relrowsecurity,'forced',c.relforcerowsecurity) ORDER BY c.relname COLLATE "C")
        FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN
        ('recipes','recipe_ingredients','recipe_steps','recipe_media','recipe_reviews','recipe_submissions')),
      'grants', (SELECT coalesce(jsonb_agg(jsonb_build_array(table_name,grantor,grantee,privilege_type,is_grantable,with_hierarchy)
        ORDER BY table_name COLLATE "C",grantor COLLATE "C",grantee COLLATE "C",privilege_type COLLATE "C",is_grantable COLLATE "C",with_hierarchy COLLATE "C"),'[]'::jsonb)
        FROM information_schema.table_privileges WHERE table_schema='public' AND table_name IN
        ('recipes','recipe_ingredients','recipe_steps','recipe_media','recipe_reviews','recipe_submissions')),
      'acl', (SELECT coalesce(jsonb_agg(jsonb_build_array(c.relname,pg_get_userbyid(a.grantor),
        CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable)
        ORDER BY c.relname COLLATE "C",pg_get_userbyid(a.grantor) COLLATE "C",
        (CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END) COLLATE "C",
        a.privilege_type COLLATE "C",a.is_grantable),'[]'::jsonb)
        FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
        CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a
        WHERE n.nspname='public' AND c.relname IN
        ('recipes','recipe_ingredients','recipe_steps','recipe_media','recipe_reviews','recipe_submissions')),
      'columns', (SELECT jsonb_agg(jsonb_build_array(table_name,column_name,udt_name,is_nullable)
        ORDER BY table_name COLLATE "C",column_name COLLATE "C",udt_name COLLATE "C",is_nullable COLLATE "C")
        FROM information_schema.columns WHERE table_schema='public' AND
          (table_name IN ('recipe_reviews','recipe_submissions') OR
          (table_name='recipes' AND column_name IN ('id','is_published','is_verified')) OR
          (table_name IN ('recipe_ingredients','recipe_steps','recipe_media') AND column_name='recipe_id'))),
      'constraints', (SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype::text,
        'definition',pg_get_constraintdef(k.oid)) ORDER BY c.relname COLLATE "C",k.conname COLLATE "C")
        FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace
        WHERE n.nspname='public' AND c.relname IN ('recipe_reviews','recipe_submissions')),
      'roles', (SELECT jsonb_agg(jsonb_build_object('name',rolname,'login',rolcanlogin,'bypassrls',rolbypassrls,'superuser',rolsuper)
        ORDER BY rolname COLLATE "C") FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')))
    INTO current_state;
    SELECT jsonb_agg(to_jsonb(c) ORDER BY table_name COLLATE "C",ordinal_position)
      INTO full_columns_now FROM information_schema.columns c WHERE table_schema='public' AND table_name IN
      ('recipes','recipe_ingredients','recipe_steps','recipe_media','recipe_reviews','recipe_submissions');
    SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid))
      ORDER BY c.relname COLLATE "C",k.conname COLLATE "C") INTO full_constraints_now
      FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relname IN
      ('recipes','recipe_ingredients','recipe_steps','recipe_media','recipe_reviews','recipe_submissions');
    IF pass = 0 THEN
      IF current_state IS DISTINCT FROM expected THEN
        RAISE EXCEPTION 'Review boundary metadata prestate differs or already applied; no policy changed';
      END IF;
      IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public'
          AND table_name IN ('recipe_reviews','recipe_submissions') AND is_generated <> 'NEVER') THEN
        RAISE EXCEPTION 'Review/submission generated-column prestate differs';
      END IF;
      full_columns_before := full_columns_now;
      full_constraints_before := full_constraints_now;
      ALTER POLICY "Public read reviews" ON public.recipe_reviews
        USING (EXISTS (SELECT 1 FROM public.recipes r
          WHERE r.id = recipe_reviews.recipe_id AND r.is_published IS TRUE AND r.is_verified IS TRUE));
      -- SYNTHETIC_TEST_AFTER_ALTER_INSERT_POINT
    ELSE
      IF current_state IS DISTINCT FROM expected_after OR full_columns_before IS DISTINCT FROM full_columns_now
          OR full_constraints_before IS DISTINCT FROM full_constraints_now THEN
        RAISE EXCEPTION 'Review boundary metadata outside the one exact predicate changed';
      END IF;
    END IF;
  END LOOP;
END
$review_boundary$;
COMMIT;
